const user = items[0]?.json || {};
let supervisorNome = "Não atribuído";
if (user.responsavel_nome) {
  supervisorNome = user.responsavel_nome;
} else if (user.lider_nome) {
  supervisorNome = user.lider_nome;
}

const colab_info = {
  nome: user.nome || "Colaborador",
  cargo: user.cargo || "Operacional",
  posto_trabalho: user.unidade_alocacao || "Não alocado",
  supervisor: supervisorNome,
  tamanho_uniforme: user.tamanho_camisa || "Não informado",
  tamanho_calca: user.tamanho_calca || "Não informado",
  tamanho_calcado: user.tamanho_sapato || "Não informado",
  escala_trabalho: user.carga_horaria || user.horario_trabalho || "07:00 às 17:00 (5x2)"
};

return [{
  json: {
    telefone: user.telefone,
    colaborador_nome: user.nome,
    colaborador_id: user.id,
    prompt_variables: JSON.stringify(colab_info, null, 2),
    mensagem_usuario: $('Webhook - Atendimento Clara').first().json.body.data.message?.conversation || $('Webhook - Atendimento Clara').first().json.body.data.message?.extendedTextMessage?.text || ""
  }
}];

